import{Tt as e,at as t,et as n,n as r,ot as i,rt as a,st as o,xt as s}from"./chunks/framework.DIOWbp6D.js";var c=JSON.parse(`{"title":"The story of Handl","description":"","frontmatter":{},"headers":[],"relativePath":"story/index.md","filePath":"story/index.md"}`),l={name:`story/index.md`};function u(r,c,l,u,d,f){let p=e(`StoryGraph`);return s(),a(`div`,null,[c[0]||=n(`h1`,{id:`the-story-of-handl`,tabindex:`-1`},[i(`The story of Handl `),n(`a`,{class:`header-anchor`,href:`#the-story-of-handl`,"aria-label":`Permalink to “The story of Handl”`},`​`)],-1),c[1]||=n(`p`,null,`How a line of research in category theory became a programming language infrastructure, and where Handl picks it up.`,-1),c[2]||=n(`h2`,{id:`a-short-history-of-arrows`,tabindex:`-1`},[i(`A short history of arrows `),n(`a`,{class:`header-anchor`,href:`#a-short-history-of-arrows`,"aria-label":`Permalink to “A short history of arrows”`},`​`)],-1),c[3]||=n(`p`,null,`The lineage below runs left to right: monads and premonoidal categories converge on Hughes's arrows, which then split into a syntax-sugar branch and a categorical-semantics branch before Sanada's work on effects and handlers funnels everything into Handl. Click any node for the details of that era.`,-1),o(p),c[4]||=t(`<p>See the full <a href="/docs/ecosystem/bibliography.html">bibliography</a>.</p><h2 id="where-handl-picks-up" tabindex="-1">Where Handl picks up <a class="header-anchor" href="#where-handl-picks-up" aria-label="Permalink to “Where Handl picks up”">​</a></h2><p>Every step above stayed inside a host language: arrows were syntax sugar in Haskell, effects were a thin layer, and the interesting structure (laws, rewrites, graded effects) was invisible to tools.</p><p>Handl inverts that. The arrow calculus isn&#39;t syntax over something else; it <strong>is the IR</strong>. Programs are 1-morphisms, laws and rewrites are 2-morphisms, and transformations are data like everything else. That gives us:</p><ul><li><strong>Inspectable computation</strong>: arrows serialize, diff, and transform.</li><li><strong>Language as data</strong>: a <code>Language</code> is declarative syntax + grammar + eval scheme + type rules, not hardcoded engine logic.</li><li><strong>Graded effects</strong>: the Graded Modal Sanada Arrow Calculus, with graded operations and handlers.</li><li><strong>Interchangeable engines</strong>: lex, parse, transform, typecheck, exec (tree-walk, bytecode, Cranelift, LLVM, Triton, CUDA) all consume the same representation.</li></ul><p>The vision: a language infrastructure where the mathematics is the substrate, and everything (tools, libraries, hosts, products) is built on top of it.</p><ul><li><a href="/docs/paradigm/">The paradigm</a>: what the calculus buys you.</li><li><a href="/docs/ecosystem/">The Handl ecosystem</a>: how the repos fit together.</li></ul>`,7)])}var d=r(l,[[`render`,u]]);export{c as __pageData,d as default};